public function index(Request $request)
{
    $user = $request->user();
    abort_unless($user && $user->canDo('controlRoom.viewAny'), 403);

    $filters = $request->validate([
        'type' => ['nullable', 'string', Rule::in(array_keys(Device::types()))],
        'activity' => ['nullable', 'string', Rule::in(['recent', 'quiet', 'never'])],
        'site_id' => ['nullable', 'integer', 'min:1'],
        'linkage' => ['nullable', 'string', Rule::in(['linked', 'unlinked'])],
    ]);
    $selectedSiteId = isset($filters['site_id'])
        ? (int) $filters['site_id']
        : null;
    if ($selectedSiteId) {
        $this->visibility->assertCanFilterSite($user, $selectedSiteId);
    }
    $canViewCanonicalDevices = $this->visibility->canViewCanonicalDevices($user);
    if (isset($filters['linkage']) && ! $canViewCanonicalDevices) {
        abort(403, UserSiteAccessService::DEFAULT_MESSAGE);
    }
    $recentSince = now()->subDay();

    $baseQuery = Device::query();
    $this->visibility->applyScope(
        $baseQuery,
        $user,
        $selectedSiteId ? [$selectedSiteId] : null,
    );

    $query = (clone $baseQuery)
        ->with([
            'signalSource:id,name,status',
            'canonicalDevice' => fn ($canonical) => $this->visibility
                ->applyCanonicalDeviceScope($canonical, $user)
                ->select([
                    'id',
                    'device_uid',
                    'name',
                    'domain',
                    'category',
                    'subcategory',
                    'status',
                    'health_status',
                    'manufacturer',
                    'model',
                    'battery_level',
                    'last_seen_at',
                ]),
        ]);

    // Join site for site name.
    $query->leftJoin('sites', 'control_room_devices.site_id', '=', 'sites.id')
        ->select('control_room_devices.*', 'sites.name as site_name');

    if (isset($filters['type'])) {
        $query->where('control_room_devices.type', $filters['type']);
    }
    if (($filters['activity'] ?? null) === 'recent') {
        $query->where('control_room_devices.last_signal_at', '>=', $recentSince);
    }
    if (($filters['activity'] ?? null) === 'quiet') {
        $query->whereNotNull('control_room_devices.last_signal_at')
            ->where('control_room_devices.last_signal_at', '<', $recentSince);
    }
    if (($filters['activity'] ?? null) === 'never') {
        $query->whereNull('control_room_devices.last_signal_at');
    }
    if (($filters['linkage'] ?? null) === 'linked') {
        $query->whereNotNull('control_room_devices.canonical_device_id');
    }
    if (($filters['linkage'] ?? null) === 'unlinked') {
        $query->whereNull('control_room_devices.canonical_device_id');
    }

    $query->orderByDesc('control_room_devices.last_signal_at')
        ->orderBy('control_room_devices.id');

    $devices = $query->paginate(48)->through(fn (Device $device): array => $this->presenter->list(
        $device,
        $this->visibility->canViewPersonalLocation($user, $device),
    ));

    // Statistics follow the same visible Site and selected-Site boundary.
    $totalSources = (clone $baseQuery)->count();
    $active24h = (clone $baseQuery)
        ->where('last_signal_at', '>=', $recentSince)
        ->count();
    $canonicalLinked = $canViewCanonicalDevices
        ? (clone $baseQuery)->whereNotNull('canonical_device_id')->count()
        : null;
    $reconciliationNeeded = $canViewCanonicalDevices
        ? (clone $baseQuery)->whereNull('canonical_device_id')->count()
        : null;

    $sites = $this->visibility->visibleSites($user)
        ->orderBy('name')
        ->get(['id', 'name'])
        ->map(fn ($s) => ['id' => $s->id, 'name' => $s->name]);

    return Inertia::render('control-room/devices/index', [
        'devices' => $devices,
        'stats' => [
            'signal_sources' => $totalSources,
            'active_24h' => $active24h,
            'canonical_linked' => $canonicalLinked,
            'reconciliation_needed' => $reconciliationNeeded,
        ],
        'filters' => [
            'type' => $filters['type'] ?? '',
            'activity' => $filters['activity'] ?? '',
            'site_id' => isset($filters['site_id']) ? (string) $filters['site_id'] : '',
            'linkage' => $filters['linkage'] ?? '',
        ],
        'sites' => $sites,
        'device_types' => Device::types(),
        'can' => [
            'view_canonical_devices' => $canViewCanonicalDevices,
        ],
        'canonicalIndexUrl' => $canViewCanonicalDevices ? '/security-devices/devices' : null,
    ]);
}

/**
 * Device detail with recent signals and linked alerts.
 * Enriches with canonical Security & Devices data where linked.
 */

public function conflicts(RosteringConflictsRequest $request)
{
    $auth = $request->user();
    abort_unless($auth && $auth->canDo('rostering.viewAny'), 403);

    $data = $request->validated();

    $week = ! empty($data['week']) ? Carbon::parse($data['week']) : now();
    $weekStart = (clone $week)->startOfWeek(Carbon::MONDAY)->startOfDay();
    $weekEnd = (clone $weekStart)->addDays(7);

    $shifts = Shift::query()
        ->with([
            'client:id,first_name,last_name',
            'site:id,name,type',
            'staff:id,name,email',
            'serviceContext:id,name,type,is_active',
            'replacementRequests' => fn ($query) => $query->active()->with([
                'requester:id,name',
                'currentStaff:id,name',
                'replacementStaff:id,name',
                'openPosition:id,replacement_request_id,status,claimed_by',
                'openPosition.claimer:id,name',
            ]),
        ])
        ->where('starts_at', '<', $weekEnd)
        ->where('ends_at', '>', $weekStart)
        ->orderBy('starts_at')
        ->get();

    $actionableShifts = $shifts
        ->filter(fn (Shift $shift) => ! in_array($shift->status, ['completed', 'cancelled'], true))
        ->values();

    $staffOverlaps = [];
    foreach ($actionableShifts->filter(fn (Shift $shift) => ! empty($shift->user_id))->groupBy('user_id') as $userId => $group) {
        $sorted = $group->sortBy('starts_at')->values();
        for ($i = 1; $i < $sorted->count(); $i++) {
            $previous = $sorted[$i - 1];
            $current = $sorted[$i];
            if ($previous && $current && $previous->ends_at && $current->starts_at && $previous->ends_at->gt($current->starts_at)) {
                $staffOverlaps[] = [
                    'staff_id' => (int) $userId,
                    'staff_name' => $current->staff?->name ?? $previous->staff?->name ?? 'Staff member',
                    'first' => $this->serializeConflictShift($previous),
                    'second' => $this->serializeConflictShift($current),
                ];
            }
        }
    }

    $clientOverlaps = [];
    foreach ($actionableShifts->groupBy('client_id') as $clientId => $group) {
        $sorted = $group->sortBy('starts_at')->values();
        for ($i = 1; $i < $sorted->count(); $i++) {
            $previous = $sorted[$i - 1];
            $current = $sorted[$i];
            if ($previous && $current && $previous->ends_at && $current->starts_at && $previous->ends_at->gt($current->starts_at)) {
                $clientOverlaps[] = [
                    'client_id' => (int) $clientId,
                    'client_name' => $current->client ? trim($current->client->first_name.' '.$current->client->last_name) : 'Client',
                    'first' => $this->serializeConflictShift($previous),
                    'second' => $this->serializeConflictShift($current),
                ];
            }
        }
    }

    $timeOffs = StaffTimeOff::query()
        ->with('user:id,name')
        ->where('starts_at', '<', $weekEnd)
        ->where('ends_at', '>', $weekStart)
        ->orderBy('starts_at')
        ->get();

    $timeOffConflicts = [];
    foreach ($actionableShifts->filter(fn (Shift $shift) => ! empty($shift->user_id)) as $shift) {
        foreach ($timeOffs->where('user_id', $shift->user_id) as $timeOff) {
            if ($timeOff->starts_at < $shift->ends_at && $timeOff->ends_at > $shift->starts_at) {
                $timeOffConflicts[] = [
                    'shift' => $this->serializeConflictShift($shift),
                    'time_off' => [
                        'id' => $timeOff->id,
                        'user_name' => $timeOff->user?->name ?? 'Staff member',
                        'type' => $timeOff->type,
                        'label' => $timeOff->label,
                        'starts_at' => optional($timeOff->starts_at)->toIso8601String(),
                        'ends_at' => optional($timeOff->ends_at)->toIso8601String(),
                    ],
                ];
                break;
            }
        }
    }

    $tightTurnarounds = [];
    foreach ($actionableShifts->filter(fn (Shift $shift) => ! empty($shift->user_id))->groupBy('user_id') as $userId => $group) {
        $sorted = $group->sortBy('starts_at')->values();
        for ($i = 1; $i < $sorted->count(); $i++) {
            $previous = $sorted[$i - 1];
            $current = $sorted[$i];

            if (! $previous?->ends_at || ! $current?->starts_at) {
                continue;
            }

            if ($previous->ends_at->gt($current->starts_at)) {
                continue;
            }

            $gapMinutes = $previous->ends_at->diffInMinutes($current->starts_at);
            if ($gapMinutes > 30) {
                continue;
            }

            $tightTurnarounds[] = [
                'staff_id' => (int) $userId,
                'staff_name' => $current->staff?->name ?? $previous->staff?->name ?? 'Staff member',
                'gap_minutes' => $gapMinutes,
                'first' => $this->serializeConflictShift($previous),
                'second' => $this->serializeConflictShift($current),
            ];
        }
    }

    $openShifts = $actionableShifts
        ->whereNull('user_id')
        ->map(fn (Shift $shift) => $this->serializeConflictShift($shift))
        ->values();

    $activeReplacements = $actionableShifts
        ->map(function (Shift $shift) {
            $replacement = $shift->replacementRequests->sortByDesc('requested_at')->first();
            if (! $replacement) {
                return null;
            }

            return [
                'id' => $replacement->id,
                'shift' => $this->serializeConflictShift($shift),
                'status' => $replacement->status,
                'reason' => $replacement->reason,
                'requested_by' => $replacement->requester?->name,
                'current_staff' => $replacement->currentStaff?->name,
                'replacement_staff' => $replacement->replacementStaff?->name,
                'claimed_by' => $replacement->openPosition?->claimer?->name,
                'open_position_id' => $replacement->openPosition?->id,
            ];
        })
        ->filter()
        ->values();

    $coverageGaps = collect($this->shiftCoverageService->buildSiteSummaries($weekStart, $weekEnd))
        ->flatMap(fn (array $site) => collect($site['alerts'] ?? [])->map(function (array $alert) use ($site) {
            return [
                ...$alert,
                'site_id' => $site['site_id'],
                'site_name' => $site['site_name'],
            ];
        }))
        ->sortByDesc(fn (array $alert) => (
            (($alert['unfilled_after_open_shifts'] ?? 0) * 100)
            + ((count($alert['planned_role_shortages'] ?? []) > 0 ? 1 : 0) * 75)
            + ((count($alert['role_shortages'] ?? []) > 0 ? 1 : 0) * 50)
            + ($alert['missing_staff'] ?? 0)
        ))
        ->values()
        ->all();
    $recurringCoverageAlignment = $this->shiftCoverageService->buildRecurringAlignment($weekStart, $weekEnd);

    return inertia('operations/rostering/conflicts', [
        'weekStart' => $weekStart->toDateString(),
        'weekEnd' => $weekEnd->toDateString(),
        'staffOverlaps' => array_values($staffOverlaps),
        'clientOverlaps' => array_values($clientOverlaps),
        'timeOffConflicts' => array_values($timeOffConflicts),
        'tightTurnarounds' => array_values($tightTurnarounds),
        'openShifts' => $openShifts,
        'activeReplacements' => $activeReplacements,
        'coverageGaps' => $coverageGaps,
        'recurringCoverageAlignment' => $recurringCoverageAlignment,
    ]);
}

public function checklistTrends(Request $request)
{
    abort_unless($request->user()?->canDo('reports.sites.view'), 403);

    $threeMonthsAgo = now()->subMonths(3);

    $failedItems = SiteChecklistResponse::where('is_failed', true)
        ->where('site_checklist_responses.created_at', '>=', $threeMonthsAgo)
        ->join('site_checklist_template_items', 'site_checklist_responses.template_item_id', '=', 'site_checklist_template_items.id')
        ->join('site_checklist_runs', 'site_checklist_responses.run_id', '=', 'site_checklist_runs.id')
        ->join('site_checklist_templates', 'site_checklist_runs.template_id', '=', 'site_checklist_templates.id')
        ->select([
            'site_checklist_runs.template_id',
            'site_checklist_templates.name as template_name',
            'site_checklist_template_items.question as item_text',
            DB::raw('COUNT(*) as failure_count'),
            DB::raw('MIN(site_checklist_responses.created_at) as first_failure'),
            DB::raw('MAX(site_checklist_responses.created_at) as last_failure'),
        ])
        ->groupBy('site_checklist_runs.template_id', 'site_checklist_templates.name', 'site_checklist_template_items.question')
        ->orderByDesc('failure_count')
        ->limit(50)
        ->get();

    return inertia('sites/reports/checklist-trends', [
        'failedItems' => $failedItems,
        'dateRange' => [
            'from' => $threeMonthsAgo->toDateString(),
            'to' => now()->toDateString(),
        ],
    ]);
}

