protected function buildSeriesDetail($seriesId): ?array
{
    if (! $seriesId) {
        return null;
    }

    $series = ShiftSeries::find($seriesId);

    if (! $series) {
        return null;
    }

    return app(ShiftSeriesPresenter::class)->detail($series);
